<section class="panel customer-list-panel"><h3>Webhook uç noktaları</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Ad</th><th>URL</th><th>Olaylar</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($endpoints as $e): ?><tr><td><?= kd_e($e['name']) ?></td><td><?= kd_e($e['url']) ?></td><td><?= kd_e(implode(', ',json_decode($e['events_json'],true)?:[])) ?></td><td><?= kd_e($e['status']) ?></td><td><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="webhook_status"><input type="hidden" name="endpoint_id" value="<?= (int)$e['id'] ?>"><input type="hidden" name="status" value="<?= $e['status']==='active'?'inactive':'active' ?>"><button class="btn secondary"><?= $e['status']==='active'?'Durdur':'Etkinleştir' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel customer-list-panel"><h3>Webhook teslimat geçmişi</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Uç nokta</th><th>Olay</th><th>Durum</th><th>Deneme</th><th>HTTP</th></tr></thead><tbody><?php foreach($deliveries as $d): ?><tr><td><?= kd_e($d['created_at']) ?></td><td><?= kd_e($d['endpoint_name']) ?></td><td><?= kd_e($d['event_name']) ?></td><td><?= kd_e($d['status']) ?></td><td><?= (int)$d['attempts'] ?></td><td><?= kd_e($d['response_code']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
